/*
 * Standalone boundary/behaviour test for the CVE-2024-23851 port.
 *
 * This test does NOT build the kernel. It replicates the exact guard
 * expressions and integer types introduced by the candidate patch in
 * drivers/md/dm-ioctl.c (copy_params) and drivers/md/dm-table.c
 * (dm_table_create) and exercises the positive and negative paths.
 *
 * Constants/helpers mirror the target 626daab3811b sources:
 *   struct dm_ioctl layout -> offsetof(data) = 48 + DM_NAME_LEN(128) + DM_UUID_LEN(129) = 305
 *   #define dm_div_up(n, sz) (((n) + (sz) - 1) / (sz))
 *   #define dm_round_up(n, sz) (dm_div_up((n), (sz)) * (sz))
 */
#include <stdio.h>
#include <stdint.h>
#include <limits.h>

#define DM_MAX_TARGETS        1048576u
#define DM_MAX_TARGET_PARAMS  1024u
#define MINIMUM_DATA_SIZE     305u
#define KEYS_PER_NODE         8u   /* representative power-of-two NODE_SIZE/sizeof(sector_t) */

#define EINVAL     22
#define ENOMEM     12
#define EOVERFLOW  75

static int failures;

static void check(const char *what, int got, int want)
{
    int ok = (got == want);
    if (!ok)
        failures++;
    printf("%-58s got=%-5d want=%-5d %s\n", what, got, want, ok ? "OK" : "FAIL");
}

/* ---- patched copy_params guard (INV-1) ---- */
static int copy_params_guard(uint32_t data_size)
{
    if ((data_size < MINIMUM_DATA_SIZE) ||
        (data_size > (DM_MAX_TARGETS * DM_MAX_TARGET_PARAMS)))
        return -EINVAL;
    return 0;
}

/* ---- pre-patch copy_params guard (for negative-path contrast) ---- */
static int copy_params_guard_prefix(uint32_t data_size)
{
    if (data_size < MINIMUM_DATA_SIZE)
        return -EINVAL;
    return 0;
}

static unsigned dm_div_up(unsigned n, unsigned sz) { return (n + sz - 1) / sz; }
#define dm_round_up(n, sz) (dm_div_up((n), (sz)) * (sz))

/* ---- patched dm_table_create flow (INV-2 + INV-3) ---- */
static int table_create_flow(unsigned num_targets)
{
    if (num_targets > DM_MAX_TARGETS)
        return -EOVERFLOW;
    if (!num_targets)
        num_targets = KEYS_PER_NODE;
    num_targets = dm_round_up(num_targets, KEYS_PER_NODE);
    if (!num_targets)
        return -EOVERFLOW;
    return 0; /* allocation path */
}

/* ---- pre-patch dm_table_create flow (for negative-path contrast) ---- */
static int table_create_flow_prefix(unsigned num_targets)
{
    unsigned int rounded;
    if (!num_targets)
        num_targets = KEYS_PER_NODE;
    rounded = dm_round_up(num_targets, KEYS_PER_NODE);
    if (!rounded)
        return -ENOMEM;
    return 0;
}

int main(void)
{
    printf("DM_MAX_TARGETS * DM_MAX_TARGET_PARAMS = %u\n",
           DM_MAX_TARGETS * DM_MAX_TARGET_PARAMS);

    /* INV-1: data_size upper bound */
    check("INV-1 data_size=0 rejected",            copy_params_guard(0), -EINVAL);
    check("INV-1 data_size=304 rejected",          copy_params_guard(304), -EINVAL);
    check("INV-1 data_size=305 accepted",          copy_params_guard(305), 0);
    check("INV-1 data_size=1073741824 accepted",   copy_params_guard(1073741824u), 0);
    check("INV-1 data_size=1073741825 rejected",   copy_params_guard(1073741825u), -EINVAL);
    check("INV-1 data_size=UINT_MAX rejected",     copy_params_guard(UINT_MAX), -EINVAL);
    check("INV-1 prefix accepted UINT_MAX",        copy_params_guard_prefix(UINT_MAX), 0);

    /* INV-2: num_targets upper bound */
    check("INV-2 num_targets=0 accepted",          table_create_flow(0), 0);
    check("INV-2 num_targets=1048576 accepted",    table_create_flow(1048576u), 0);
    check("INV-2 num_targets=1048577 rejected",    table_create_flow(1048577u), -EOVERFLOW);
    check("INV-2 num_targets=UINT_MAX rejected",   table_create_flow(UINT_MAX), -EOVERFLOW);

    /* INV-3: overflow-to-zero reporting (KEYS_PER_NODE=8) */
    check("INV-3 round_up(UINT_MAX-6,8)==0",       (int)dm_round_up(UINT_MAX - 6u, KEYS_PER_NODE), 0);
    check("INV-3 guard rejects overflowing count", table_create_flow(UINT_MAX - 6u), -EOVERFLOW);
    check("INV-3 prefix returned -ENOMEM",         table_create_flow_prefix(UINT_MAX - 6u), -ENOMEM);

    if (failures) {
        printf("\nRESULT: FAIL (%d)\n", failures);
        return 1;
    }
    printf("\nRESULT: PASS (all boundary assertions hold)\n");
    return 0;
}

